void TtsInstanceProxy::Init(
    ::mojo::PendingRemote<TtsHost> in_host_remote, InitCallback callback) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send arc::mojom::TtsInstance::Init", "input_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("host_remote"), in_host_remote,
                        "<value of type ::mojo::PendingRemote<TtsHost>>");
   });
#endif

  const bool kExpectsResponse = true;
  const bool kIsSync = false;
  const bool kAllowInterrupt = true;
  const bool is_urgent = false;
  
  const uint32_t kFlags =
      ((kExpectsResponse) ? mojo::Message::kFlagExpectsResponse : 0) |
      ((kIsSync) ? mojo::Message::kFlagIsSync : 0) |
      ((kAllowInterrupt) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((is_urgent) ? mojo::Message::kFlagIsUrgent : 0);
  
  mojo::Message message(
      internal::kTtsInstance_Init_Name, kFlags, 0, 0, nullptr);
  mojo::internal::MessageFragment<
      ::arc::mojom::internal::TtsInstance_Init_Params_Data> params(
          message);
  params.Allocate();
  mojo::internal::Serialize<mojo::InterfacePtrDataView<::arc::mojom::TtsHostInterfaceBase>>(
      in_host_remote, &params->host_remote, &params.message());
  MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
      !mojo::internal::IsHandleOrInterfaceValid(params->host_remote),
      mojo::internal::VALIDATION_ERROR_UNEXPECTED_INVALID_HANDLE,
      "invalid host_remote in TtsInstance.Init request");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(TtsInstance::Name_);
  message.set_method_name("Init");
#endif
  std::unique_ptr<mojo::MessageReceiver> responder(
      new TtsInstance_Init_ForwardToCallback(
          std::move(callback)));
  ::mojo::internal::SendMojoMessage(*receiver_, message, std::move(responder));
}

void TtsInstanceProxy::Speak(
    TtsUtterancePtr in_utterance) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send arc::mojom::TtsInstance::Speak", "input_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("utterance"), in_utterance,
                        "<value of type TtsUtterancePtr>");
   });
#endif

  const bool kExpectsResponse = false;
  const bool kIsSync = false;
  const bool kAllowInterrupt = true;
  const bool is_urgent = false;
  
  const uint32_t kFlags =
      ((kExpectsResponse) ? mojo::Message::kFlagExpectsResponse : 0) |
      ((kIsSync) ? mojo::Message::kFlagIsSync : 0) |
      ((kAllowInterrupt) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((is_urgent) ? mojo::Message::kFlagIsUrgent : 0);
  
  mojo::Message message(
      internal::kTtsInstance_Speak_Name, kFlags, 0, 0, nullptr);
  mojo::internal::MessageFragment<
      ::arc::mojom::internal::TtsInstance_Speak_Params_Data> params(
          message);
  params.Allocate();
  mojo::internal::MessageFragment<
      typename decltype(params->utterance)::BaseType> utterance_fragment(
          params.message());
  mojo::internal::Serialize<::arc::mojom::TtsUtteranceDataView>(
      in_utterance, utterance_fragment);
  params->utterance.Set(
      utterance_fragment.is_null() ? nullptr : utterance_fragment.data());
  MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
      params->utterance.is_null(),
      mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
      "null utterance in TtsInstance.Speak request");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(TtsInstance::Name_);
  message.set_method_name("Speak");
#endif
  // This return value may be ignored as false implies the Connector has
  // encountered an error, which will be visible through other means.
  ::mojo::internal::SendMojoMessage(*receiver_, message);
}

