class TtsInstance_Init_ProxyToResponder : public ::mojo::internal::ProxyToResponder {
 public:
  static TtsInstance::InitCallback CreateCallback(
      ::mojo::Message& message,
      std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
    std::unique_ptr<TtsInstance_Init_ProxyToResponder> proxy(
        new TtsInstance_Init_ProxyToResponder(
            message, std::move(responder)));
    return base::BindOnce(&TtsInstance_Init_ProxyToResponder::Run,
                          std::move(proxy));
  }

  ~TtsInstance_Init_ProxyToResponder() {
#if DCHECK_IS_ON()
    if (responder_) {
      // If we're being destroyed without being run, we want to ensure the
      // binding endpoint has been closed. This checks for that asynchronously.
      // We pass a bound generated callback to handle the response so that any
      // resulting DCHECK stack will have useful interface type information.
      // Instantiate a ScopedFizzleBlockShutdownTasks to allow this request to
      // fizzle if this happens after shutdown and the endpoint is bound to a
      // BLOCK_SHUTDOWN sequence.
      base::ThreadPoolInstance::ScopedFizzleBlockShutdownTasks fizzler;
      responder_->IsConnectedAsync(base::BindOnce(&OnIsConnectedComplete));
    }
#endif
  }

 private:
  TtsInstance_Init_ProxyToResponder(
      ::mojo::Message& message,
      std::unique_ptr<mojo::MessageReceiverWithStatus> responder)
      : ::mojo::internal::ProxyToResponder(message, std::move(responder)) {
  }

#if DCHECK_IS_ON()
  static void OnIsConnectedComplete(bool connected) {
    DCHECK(!connected)
        << "TtsInstance::InitCallback was destroyed without "
        << "first either being run or its corresponding binding being closed. "
        << "It is an error to drop response callbacks which still correspond "
        << "to an open interface pipe.";
  }
#endif

  void Run(
      );
};

bool TtsInstance_Init_ForwardToCallback::Accept(
    mojo::Message* message) {

  DCHECK(message->is_serialized());
  internal::TtsInstance_Init_ResponseParams_Data* params =
      reinterpret_cast<
          internal::TtsInstance_Init_ResponseParams_Data*>(
              message->mutable_payload());
  
  
  // Validation for TtsInstance.3
  bool success = true;
  TtsInstance_Init_ResponseParamsDataView input_data_view(params, message);
  
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        TtsInstance::Name_, 3, true);
    return false;
  }
  if (!callback_.is_null())
    std::move(callback_).Run();
  return true;
}

void TtsInstance_Init_ProxyToResponder::Run(
    ) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT0("mojom", "Send reply arc::mojom::TtsInstance::Init");
#endif
  
  const uint32_t kFlags = mojo::Message::kFlagIsResponse |
      ((is_sync_) ? mojo::Message::kFlagIsSync : 0) |
      ((true) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((false) ? mojo::Message::kFlagIsUrgent : 0);
  
  mojo::Message message(
      internal::kTtsInstance_Init_Name, kFlags, 0, 0, nullptr);
  mojo::internal::MessageFragment<
      ::arc::mojom::internal::TtsInstance_Init_ResponseParams_Data> params(
          message);
  params.Allocate();

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(TtsInstance::Name_);
  message.set_method_name("Init");
#endif

  message.set_request_id(request_id_);
  message.set_trace_nonce(trace_nonce_);
  ::mojo::internal::SendMojoMessage(*responder_, message);
  // SendMojoMessage() fails silently if the responder connection is closed,
  // or if the message is malformed.
  //
  // TODO(darin): If Accept() returns false due to a malformed message, that
  // may be good reason to close the connection. However, we don't have a
  // way to do that from here. We should add a way.
  responder_ = nullptr;
}

// static
bool TtsInstanceStubDispatch::Accept(
    TtsInstance* impl,
    mojo::Message* message) {
  switch (message->header()->name) {
    case internal::kTtsInstance_Init_Name: {
      break;
    }
    case internal::kTtsInstance_Speak_Name: {

      DCHECK(message->is_serialized());
      internal::TtsInstance_Speak_Params_Data* params =
          reinterpret_cast<internal::TtsInstance_Speak_Params_Data*>(
              message->mutable_payload());
      
      
      // Validation for TtsInstance.1
      bool success = true;
      TtsUtterancePtr p_utterance{};
      TtsInstance_Speak_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadUtterance(&p_utterance))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            TtsInstance::Name_, 1, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Speak(        
        std::move(p_utterance));
      return true;
    }
    case internal::kTtsInstance_Stop_Name: {

      DCHECK(message->is_serialized());
      internal::TtsInstance_Stop_Params_Data* params =
          reinterpret_cast<internal::TtsInstance_Stop_Params_Data*>(
              message->mutable_payload());
      
      
      // Validation for TtsInstance.2
      bool success = true;
      TtsInstance_Stop_ParamsDataView input_data_view(params, message);
      
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            TtsInstance::Name_, 2, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Stop(        );
      return true;
    }
    case internal::kTtsInstance_RefreshVoices_Name: {

      DCHECK(message->is_serialized());
      internal::TtsInstance_RefreshVoices_Params_Data* params =
          reinterpret_cast<internal::TtsInstance_RefreshVoices_Params_Data*>(
              message->mutable_payload());
      
      
      // Validation for TtsInstance.4
      bool success = true;
      TtsInstance_RefreshVoices_ParamsDataView input_data_view(params, message);
      
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            TtsInstance::Name_, 4, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->RefreshVoices(        );
      return true;
    }
  }
  return false;
}

// static
bool TtsInstanceStubDispatch::AcceptWithResponder(
    TtsInstance* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (message->header()->name) {
    case internal::kTtsInstance_Init_Name: {

      internal::TtsInstance_Init_Params_Data* params =
          reinterpret_cast<
              internal::TtsInstance_Init_Params_Data*>(
                  message->mutable_payload());
      
      
      // Validation for TtsInstance.3
      bool success = true;
      ::mojo::PendingRemote<TtsHost> p_host_remote{};
      TtsInstance_Init_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_host_remote =
            input_data_view.TakeHostRemote<decltype(p_host_remote)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            TtsInstance::Name_, 3, false);
        return false;
      }
      TtsInstance::InitCallback callback =
          TtsInstance_Init_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Init(        
        std::move(p_host_remote), std::move(callback));
      return true;
    }
    case internal::kTtsInstance_Speak_Name: {
      break;
    }
    case internal::kTtsInstance_Stop_Name: {
      break;
    }
    case internal::kTtsInstance_RefreshVoices_Name: {
      break;
    }
  }
  return false;
}
